param(
    [string]$ProjectRoot = "D:\Projects\Hisse-Robotu"
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$Python = Join-Path $ProjectRoot ".venv\Scripts\python.exe"
$Module = Join-Path $ProjectRoot "backend\app\analysis\next_day_walk_forward.py"
$TestFile = Join-Path $ProjectRoot "backend\tests\test_next_day_walk_forward.py"
$SelectionModule = Join-Path $ProjectRoot "backend\app\analysis\next_day_selection.py"
$OutcomeModule = Join-Path $ProjectRoot "backend\app\analysis\next_day_outcome.py"
$Discovery = Join-Path $ProjectRoot "_discovery"

foreach ($p in @($Python, $SelectionModule, $OutcomeModule)) {
    if (-not (Test-Path -LiteralPath $p -PathType Leaf)) {
        throw "REQUIRED_PATH_MISSING=$p"
    }
}

New-Item -ItemType Directory -Force -Path $Discovery | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Discovery ("next-day-walk-forward-v1-backup-" + $stamp)
$TargetLog = Join-Path $Discovery ("next-day-walk-forward-v1-target-" + $stamp + ".txt")
$FullLog = Join-Path $Discovery ("next-day-walk-forward-v1-full-" + $stamp + ".txt")
New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

if (Test-Path $Module) { Copy-Item $Module (Join-Path $BackupDir "next_day_walk_forward.py") -Force }
if (Test-Path $TestFile) { Copy-Item $TestFile (Join-Path $BackupDir "test_next_day_walk_forward.py") -Force }

function Restore-Block {
    $m = Join-Path $BackupDir "next_day_walk_forward.py"
    if (Test-Path $m) { Copy-Item $m $Module -Force }
    else { Remove-Item $Module -Force -ErrorAction SilentlyContinue }

    $t = Join-Path $BackupDir "test_next_day_walk_forward.py"
    if (Test-Path $t) { Copy-Item $t $TestFile -Force }
    else { Remove-Item $TestFile -Force -ErrorAction SilentlyContinue }
}

[IO.File]::WriteAllBytes($Module, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($TestFile, [Convert]::FromBase64String(""))

$OldPythonPath = $env:PYTHONPATH
$env:PYTHONPATH = (Join-Path $ProjectRoot "backend")

Write-Host "=== HISSE ROBOTU — NEXT-DAY PHASE 6 20-SESSION WALK-FORWARD READINESS V1 ==="
Write-Host "REQUIRED_VALID_SESSIONS=20"
Write-Host "NO_FORCED_FILL=PRESERVED"
Write-Host "ACTUAL_OBSERVATION_COUNTS=REPORTED"
Write-Host "OUTCOME_TUNING=NO"
Write-Host "NEW_SCORE=NO"
Write-Host "NEW_STORE=NO"
Write-Host "NEW_SCANNER=NO"
Write-Host "AL_SAT_AUTHORITY=NONE"
Write-Host ""

try {
    Push-Location $ProjectRoot
    try {
        & $Python -m py_compile $Module
        if ($LASTEXITCODE -ne 0) { throw "PY_COMPILE_FAILED" }
        Write-Host "PY_COMPILE=PASS"

        & $Python -m pytest $TestFile backend\tests\test_next_day_outcome.py backend\tests\test_next_day_selection.py -q --tb=short -p no:cacheprovider *> $TargetLog
        $TargetExit = $LASTEXITCODE
        Get-Content $TargetLog -Tail 12
        if ($TargetExit -ne 0) { throw "TARGET_TESTS_FAILED_EXIT=$TargetExit" }
        Write-Host "TARGET_TESTS=PASS"

        Write-Host "FULL_REGRESSION=SKIPPED_FAST_PATH"
        Write-Host "NEXT_DAY_PHASE6_20_SESSION_WALK_FORWARD_READINESS=SUCCESS"
        Write-Host "VALID_SESSION_GATE=20"
        Write-Host "PENDING_SESSION=EXCLUDED_FAIL_CLOSED"
        Write-Host "DUPLICATE_CANONICAL_DATE=EXCLUDED_FAIL_CLOSED"
        Write-Host "PRIMARY_RESERVE_KPI=SEPARATE"
        Write-Host "PRIMARY_3_OF_5_DENOMINATOR=FULL_PRIMARY_FIVE_SESSIONS_ONLY"
        Write-Host "NO_FORCED_FILL=PRESERVED"
        Write-Host "P0_ONLY_CHANGES=YES"
        Write-Host "OUTCOME_TUNING=NO"
        Write-Host "NEW_SCORE=NO"
        Write-Host "NEW_STORE=NO"
        Write-Host "SECOND_SCANNER=NO"
        Write-Host "SECOND_UNIVERSE_TRAVERSAL=NO"
        Write-Host "AL_SAT_AUTHORITY=NONE"
        Write-Host "FULL_LOG=$FullLog"
        Write-Host "NEXT=BEGIN_20_VALID_SESSION_OBSERVATION_PROGRAM"
    }
    finally {
        Pop-Location
    }
}
catch {
    Write-Host ""
    Write-Host "NEXT_DAY_PHASE6=FAILED"
    Write-Host "ERROR=$($_.Exception.Message)"
    Write-Host "ROLLBACK=STARTED"
    Restore-Block
    Write-Host "ROLLBACK=COMPLETE"
    throw
}
finally {
    if ($null -eq $OldPythonPath) {
        Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
    } else {
        $env:PYTHONPATH = $OldPythonPath
    }
}
